// DINERO 30-oct-2026 12:00 · Mil dólares guardados en casa y la inflación (método V2)
// Metáfora: el fajo de billetes que se ENCOGE mientras las etiquetas de precio se inflan alrededor.
// Sitios: A = la caja bajo el colchón (verde oscuro, luz cálida de lámpara arriba a la izquierda);
//         B = la bóveda asegurada (azul marino) solo para la solución.
import React from 'react';
import {AbsoluteFill, Easing, interpolate, clamp, useS, en, golpe, sacudida, Etiqueta, Contador, Camara, Destello, Ondas, Estela, FONT} from './kit';

export const SUBS = {acento: '#FFC83D'};

const ORO = '#FFC83D';
const ROJO = '#FF4D4D';
const VERDE = '#4fd18b';

const T_ENCOG = en('encogieron');
const T_BILLETE = en('billete');
const T_PRECIOS = en('precios');
const T_CRECEN = en('crecieron');
const T_VEINTE = en('veinte');
const T_VEINTICINCO = en('veinticinco');
const T_VEINTICUATRO = en('veinticuatro');
const T_CIEN = en('cien');
const T_CIENTO = en('ciento');
const T_MIL4 = en('mil', 4);
const T_OCHO = en('ochocientos');
const T_DOSC = en('doscientos');
const T_CAJA = en('caja');
const T_DEJA = en('Deja');
const T_URG = en('urgencia');
const T_RESTO = en('resto');
const T_ASEG = en('asegurada');
const T_INFL = en('inflación');
const T_ENVIA = en('Envíaselo');
const T_COLCHON = en('colchón');

// tamaño del fajo: 1 al inicio, 0.804 tras "ochocientos"
const escalaFajo = (s: number) => {
  const a = interpolate(s, [0.2, 1.2], [1.04, 0.97], {...clamp, easing: Easing.out(Easing.cubic)});
  const b = interpolate(s, [T_OCHO - 0.1, T_OCHO + 0.7], [1, 0.804], {...clamp, easing: Easing.inOut(Easing.cubic)});
  return Math.min(a, 1) * b;
};

const FondoCasa: React.FC<{boveda: boolean}> = ({boveda}) => {
  const {s} = useS();
  const c = boveda ? ['#22457e', '#0f2148', '#040a1a'] : ['#2c5a46', '#12302a', '#050f0c'];
  return (
    <AbsoluteFill style={{background: `radial-gradient(ellipse at 25% 18%, ${c[0]} 0%, ${c[1]} 50%, ${c[2]} 100%)`}}>
      <div style={{position: 'absolute', left: -240, top: -240, width: 980, height: 980, borderRadius: 980, background: 'radial-gradient(circle, rgba(255,214,140,0.18), transparent 64%)'}} />
      {/* textura de pared: tablones */}
      <svg width={1080} height={1920} style={{position: 'absolute', opacity: 0.12}}>
        {Array.from({length: 12}).map((_, i) => <line key={i} x1={i * 96} y1={0} x2={i * 96} y2={1920} stroke="#ffffff" strokeWidth={3} />)}
      </svg>
      {Array.from({length: 8}).map((_, i) => {
        const r = 100 + ((i * 61) % 110);
        return <div key={i} style={{position: 'absolute', left: ((i * 271) % 1160) - 60 + Math.sin(s * 0.3 + i) * 30, top: ((i * 433) % 1900) + Math.cos(s * 0.27 + i) * 40, width: r, height: r, borderRadius: r, background: i % 2 ? 'rgba(255,200,61,0.09)' : 'rgba(140,255,200,0.07)', filter: 'blur(24px)'}} />;
      })}
      <AbsoluteFill style={{background: 'radial-gradient(circle at 50% 50%, transparent 50%, rgba(0,0,0,0.66) 100%)'}} />
    </AbsoluteFill>
  );
};

const Defs: React.FC = () => (
  <defs>
    <linearGradient id="billG" x1="0" y1="0" x2="1" y2="1">
      <stop offset="0%" stopColor="#c9f2c4" />
      <stop offset="50%" stopColor="#7cc483" />
      <stop offset="100%" stopColor="#3f7d4c" />
    </linearGradient>
    <linearGradient id="cajaG" x1="0" y1="0" x2="1" y2="1">
      <stop offset="0%" stopColor="#c99a62" />
      <stop offset="60%" stopColor="#8a5f33" />
      <stop offset="100%" stopColor="#5a3b1d" />
    </linearGradient>
    <linearGradient id="colchonG" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0%" stopColor="#f1f4ff" />
      <stop offset="100%" stopColor="#a9b4d6" />
    </linearGradient>
    <linearGradient id="tagG" x1="0" y1="0" x2="1" y2="1">
      <stop offset="0%" stopColor="#fff3c4" />
      <stop offset="100%" stopColor="#e0a92a" />
    </linearGradient>
    <linearGradient id="bovedaG" x1="0" y1="0" x2="1" y2="1">
      <stop offset="0%" stopColor="#c7d3ea" />
      <stop offset="55%" stopColor="#7d8db0" />
      <stop offset="100%" stopColor="#3d4a68" />
    </linearGradient>
  </defs>
);

// Un billete con volumen
const Billete: React.FC<{x: number; y: number; w?: number; rot?: number; alpha?: number; rojo?: number}> = ({x, y, w = 420, rot = 0, alpha = 1, rojo = 0}) => {
  const h = w * 0.45;
  return (
    <g transform={`translate(${x} ${y}) rotate(${rot})`} opacity={alpha}>
      <rect x={-w / 2 + 8} y={-h / 2 + 12} width={w} height={h} rx={14} fill="rgba(0,0,0,0.3)" />
      <rect x={-w / 2} y={-h / 2} width={w} height={h} rx={14} fill="url(#billG)" stroke="#2f6a3a" strokeWidth={5} />
      <rect x={-w / 2 + 16} y={-h / 2 + 16} width={w - 32} height={h - 32} rx={10} fill="none" stroke="rgba(30,80,40,0.55)" strokeWidth={4} />
      <circle r={h * 0.3} fill="rgba(255,255,255,0.35)" stroke="#2f6a3a" strokeWidth={4} />
      <text y={h * 0.11} textAnchor="middle" fontFamily={FONT} fontWeight={800} fontSize={h * 0.3} fill="#245a30">100</text>
      <rect x={-w / 2 + 10} y={-h / 2 + 8} width={w * 0.5} height={10} rx={5} fill="rgba(255,255,255,0.45)" />
      {rojo > 0 && <rect x={-w / 2} y={-h / 2} width={w} height={h} rx={14} fill={ROJO} opacity={rojo * 0.55} />}
    </g>
  );
};

// La caja bajo el colchón con el fajo de diez billetes
const CajaColchon: React.FC = () => {
  const {s, spr, lin} = useS();
  const k = escalaFajo(s);
  const levanta = 1 - lin(T_DEJA - 0.3, T_DEJA, 0, 1) + lin(T_ENVIA - 0.3, T_ENVIA, 0, 1);
  const fuga = lin(T_DOSC, T_CAJA + 0.4, 0, 1);
  const urg = lin(T_URG - 0.1, T_URG + 0.4, 0, 1);
  const fajo = Array.from({length: 10}).map((_, i) => {
    const vaSeFuga = i >= 8;
    const dx = vaSeFuga ? fuga * (i === 8 ? -380 : 380) : 0;
    const dy = vaSeFuga ? -fuga * 520 : 0;
    const al = vaSeFuga ? 1 - fuga : i < 3 || urg === 0 ? 1 : 1 - urg;
    return <Billete key={i} x={540 + dx + Math.sin(s * 1.4 + i) * 2} y={1240 - i * 16 + dy} rot={(i % 3) - 1 + (vaSeFuga ? fuga * 30 * (i === 8 ? -1 : 1) : 0)} alpha={al} rojo={vaSeFuga ? lin(T_DOSC - 0.1, T_DOSC + 0.2, 0, 1) : 0} />;
  });
  return (
    <svg width={1080} height={1920} viewBox="0 0 1080 1920" style={{position: 'absolute'}}>
      <Defs />
      <ellipse cx={560} cy={1500} rx={460} ry={50} fill="rgba(0,0,0,0.45)" style={{filter: 'blur(14px)'}} />
      {/* caja */}
      <path d="M 180 1160 L 900 1160 L 880 1480 L 200 1480 Z" fill="url(#cajaG)" stroke="#3e2712" strokeWidth={8} />
      <path d="M 180 1160 L 900 1160 L 860 1110 L 220 1110 Z" fill="#6e4a26" />
      <rect x={210} y={1180} width={40} height={280} rx={16} fill="rgba(255,255,255,0.14)" />
      <g transform={`translate(540 1250) scale(${k}) translate(-540 -1250)`}>{fajo}</g>
      {/* colchón levantado */}
      <g transform={`translate(0 ${-260 * levanta + Math.sin(s * 1.2) * 6}) rotate(${-6 * levanta} 160 1080)`}>
        <rect x={100} y={940} width={880} height={170} rx={60} fill="url(#colchonG)" stroke="#7e89ad" strokeWidth={6} />
        {Array.from({length: 6}).map((_, i) => <circle key={i} cx={200 + i * 135} cy={1025} r={10} fill="#8c97bb" />)}
        <rect x={140} y={955} width={600} height={24} rx={12} fill="rgba(255,255,255,0.6)" />
      </g>
    </svg>
  );
};

// Etiquetas de precio que se inflan alrededor del fajo
const Etiquetas: React.FC = () => {
  const {s, spr, lin} = useS();
  if (s < T_PRECIOS - 0.2 || s > T_DOSC) return null;
  const infla = 1 + 0.24 * lin(T_VEINTE, T_VEINTICUATRO + 0.4, 0, 1);
  const pos = [[210, 760], [860, 820], [180, 1600], [880, 1620]];
  return (
    <svg width={1080} height={1920} viewBox="0 0 1080 1920" style={{position: 'absolute'}}>
      <Defs />
      {pos.map(([x, y], i) => {
        const e = spr(T_PRECIOS + i * 0.12, 10, 170) * infla * (1 + 0.03 * Math.sin(s * 5 + i));
        return (
          <g key={i} transform={`translate(${x} ${y}) scale(${e}) rotate(${i % 2 ? 10 : -10})`}>
            <path d="M -90 -50 L 60 -50 L 100 0 L 60 50 L -90 50 Z" fill="url(#tagG)" stroke="#a3721a" strokeWidth={5} />
            <circle cx={55} cy={0} r={11} fill="#5a3b1d" />
            <text x={-20} y={16} textAnchor="middle" fontFamily={FONT} fontWeight={800} fontSize={46} fill="#5a3b1d">$</text>
            <ellipse cx={-50} cy={-30} rx={26} ry={9} fill="rgba(255,255,255,0.6)" />
          </g>
        );
      })}
    </svg>
  );
};

// Producto de cien que pasa a ciento veinticuatro
const Producto: React.FC = () => {
  const {s, spr, lin} = useS();
  if (s < T_CIEN - 0.3 || s > T_MIL4) return null;
  const e = spr(T_CIEN - 0.2, 11, 160) * lin(T_MIL4 - 0.3, T_MIL4, 1, 0);
  const crece = 1 + 0.24 * spr(T_CIENTO, 9, 160);
  return (
    <svg width={1080} height={1920} viewBox="0 0 1080 1920" style={{position: 'absolute', transform: `scale(${e})`, transformOrigin: '540px 760px'}}>
      <defs>
        <linearGradient id="bolsaG" x1="0" y1="0" x2="1" y2="1">
          <stop offset="0%" stopColor="#ffe9c9" />
          <stop offset="100%" stopColor="#c58a4a" />
        </linearGradient>
      </defs>
      <ellipse cx={560} cy={900} rx={190} ry={22} fill="rgba(0,0,0,0.4)" style={{filter: 'blur(8px)'}} />
      <g transform={`translate(540 760) scale(${crece}) translate(-540 -760)`}>
        <path d="M 400 620 L 680 620 L 700 890 L 380 890 Z" fill="url(#bolsaG)" stroke="#7a4d1f" strokeWidth={6} />
        <path d="M 450 620 Q 540 520 630 620" stroke="#7a4d1f" strokeWidth={14} fill="none" />
        <rect x={410} y={640} width={26} height={220} rx={12} fill="rgba(255,255,255,0.4)" />
        <circle cx={500} cy={600} r={40} fill="#ffcf5a" />
        <circle cx={580} cy={590} r={34} fill="#6bc06b" />
      </g>
    </svg>
  );
};

// Sitio B: bóveda asegurada con escudo y una plantita que crece
const Boveda: React.FC = () => {
  const {s, spr, lin} = useS();
  const e = spr(T_RESTO - 0.05, 12, 150);
  const escudo = spr(T_ASEG, 9, 200);
  const balanza = lin(T_INFL - 0.2, T_INFL + 0.6, 0, 1);
  const inclina = Math.sin(s * 2) * 6 * balanza;
  return (
    <svg width={1080} height={1920} viewBox="0 0 1080 1920" style={{position: 'absolute', transform: `scale(${0.7 + 0.3 * e})`, transformOrigin: '540px 1150px'}}>
      <Defs />
      <ellipse cx={560} cy={1520} rx={420} ry={44} fill="rgba(0,0,0,0.45)" style={{filter: 'blur(12px)'}} />
      <rect x={200} y={820} width={680} height={680} rx={60} fill="url(#bovedaG)" stroke="#2c3550" strokeWidth={10} />
      <circle cx={540} cy={1160} r={220} fill="#55658a" stroke="#2c3550" strokeWidth={10} />
      {Array.from({length: 8}).map((_, i) => {
        const a = (i / 8) * Math.PI * 2 + s * 0.6;
        return <line key={i} x1={540} y1={1160} x2={540 + Math.cos(a) * 180} y2={1160 + Math.sin(a) * 180} stroke="#c7d3ea" strokeWidth={14} strokeLinecap="round" />;
      })}
      <circle cx={540} cy={1160} r={50} fill="#c7d3ea" />
      <rect x={230} y={850} width={36} height={600} rx={18} fill="rgba(255,255,255,0.22)" />
      {/* escudo de seguro */}
      <g transform={`translate(840 860) scale(${escudo})`}>
        <path d="M 0 -110 L 95 -70 Q 95 60 0 120 Q -95 60 -95 -70 Z" fill={ORO} stroke="#9a6a12" strokeWidth={8} />
        <path d="M -40 0 L -10 34 L 48 -34" stroke="#5a3b1d" strokeWidth={16} fill="none" strokeLinecap="round" />
        <ellipse cx={-40} cy={-70} rx={26} ry={12} fill="rgba(255,255,255,0.6)" />
      </g>
      {/* balanza interés contra inflación */}
      {balanza > 0 && (
        <g opacity={balanza} transform={`translate(540 700) rotate(${inclina})`}>
          <line x1={-220} y1={0} x2={220} y2={0} stroke={ORO} strokeWidth={12} strokeLinecap="round" />
          <circle cx={-220} cy={40} r={56} fill={VERDE} stroke="#1e6b42" strokeWidth={6} />
          <circle cx={220} cy={40} r={56} fill={ROJO} stroke="#8e1d1d" strokeWidth={6} />
          <text x={-220} y={58} textAnchor="middle" fontFamily={FONT} fontWeight={800} fontSize={48} fill="#0b2a18">%</text>
          <text x={220} y={58} textAnchor="middle" fontFamily={FONT} fontWeight={800} fontSize={48} fill="#3a0b0b">%</text>
        </g>
      )}
    </svg>
  );
};

const Avion: React.FC = () => {
  const {lin} = useS();
  const p = lin(T_COLCHON - 0.2, T_COLCHON + 1.3, 0, 1, Easing.in(Easing.quad));
  if (p <= 0 || p >= 1) return null;
  return (
    <svg width={170} height={170} viewBox="0 0 100 100" style={{position: 'absolute', left: 520 + p * 560, top: 1150 - p * 800 - Math.sin(p * Math.PI) * 150, transform: `rotate(-28deg) scale(${1.1 - p * 0.5})`}}>
      <polygon points="5,50 95,10 60,90 48,58" fill="#ffffff" />
      <polygon points="48,58 95,10 40,70" fill="#b9c8ea" />
    </svg>
  );
};

export const Escena: React.FC = () => {
  const {s, lin} = useS();
  const enB = s >= T_RESTO - 0.02 && s < T_ENVIA - 0.02;
  const sh = sacudida(s, [T_OCHO + 0.6, T_DOSC], 13);
  const deriva = Math.sin(s * 0.55) * 12;
  const paradasA = [
    {t: 0, x: 540, y: 1200, zoom: 1.12},
    {t: T_ENCOG + 0.4, x: 540, y: 1220, zoom: 1.3},
    {t: T_BILLETE + 0.3, x: 540, y: 1200, zoom: 1.6},
    {t: T_CRECEN, x: 540, y: 1120, zoom: 0.95},
    {t: T_VEINTICUATRO + 0.4, x: 540, y: 1100, zoom: 1.0},
    {t: T_CIEN, x: 540, y: 900, zoom: 1.2},
    {t: T_CIENTO + 0.4, x: 540, y: 880, zoom: 1.35},
    {t: T_MIL4, x: 540, y: 1220, zoom: 1.4},
    {t: T_OCHO + 0.7, x: 540, y: 1230, zoom: 1.6},
    {t: T_DOSC + 0.2, x: 540, y: 1080, zoom: 1.0},
    {t: T_URG + 0.5, x: 540, y: 1220, zoom: 1.35},
    {t: T_RESTO, x: 540, y: 1200, zoom: 1.25},
  ];
  const paradasB = [
    {t: T_RESTO, x: 540, y: 1160, zoom: 1.0},
    {t: T_ASEG + 0.5, x: 640, y: 1040, zoom: 1.3},
    {t: T_INFL + 0.4, x: 540, y: 900, zoom: 1.15},
    {t: T_ENVIA, x: 540, y: 1000, zoom: 1.05},
  ];
  const paradasC = [
    {t: T_ENVIA, x: 540, y: 1200, zoom: 1.3},
    {t: T_ENVIA + 2.5, x: 540, y: 1180, zoom: 1.0},
  ];
  return (
    <AbsoluteFill>
      <FondoCasa boveda={enB} />
      <AbsoluteFill style={{transform: `translate(${sh.x + deriva}px, ${sh.y}px)`}}>
        {!enB && (
          <Camara paradas={s < T_RESTO ? paradasA : paradasC} centroY={1080}>
            <CajaColchon />
            <Etiquetas />
            <Producto />
            <Ondas x={540} y={1200} t0={T_OCHO + 0.6} color={ROJO} />
            {s > T_BILLETE && s < T_PRECIOS + 0.4 && <Etiqueta texto="$1,000" x={820} y={1000} px={640} py={1150} t0={T_BILLETE} color={ORO} />}
          </Camara>
        )}
        {enB && (
          <Camara paradas={paradasB} centroY={1080}>
            <Boveda />
            <Ondas x={840} y={860} t0={T_ASEG} color={ORO} />
          </Camara>
        )}
        <Estela t0={T_DOSC} t1={T_CAJA + 0.3} copias={3} render={(t, al) => (
          <div style={{position: 'absolute', left: 120 + interpolate(t, [T_DOSC, T_CAJA + 0.4], [300, 0], clamp), top: 1100 - interpolate(t, [T_DOSC, T_CAJA + 0.4], [0, 400], clamp), width: 120, height: 54, borderRadius: 10, background: ROJO, opacity: al}} />
        )} />
        <Avion />
      </AbsoluteFill>
      {s < T_VEINTE && <Contador desde={1000} hasta={1000} t0={0.05} t1={0.4} y={430} prefijo="$" color={VERDE} />}
      {s >= T_VEINTE && s < T_VEINTICUATRO && <Etiqueta texto="2020" x={300} y={440} px={300} py={520} t0={T_VEINTE} color={ORO} size={56} />}
      {s >= T_VEINTICINCO && s < T_VEINTICUATRO && <Etiqueta texto="2025" x={780} y={440} px={780} py={520} t0={T_VEINTICINCO} color={ROJO} size={56} />}
      {s >= T_VEINTICUATRO && s < T_CIEN && <Contador desde={0} hasta={24} t0={T_VEINTICUATRO} t1={T_VEINTICUATRO + 0.7} y={430} prefijo="+" sufijo="%" color={ROJO} />}
      {s >= T_CIEN && s < T_MIL4 && <Contador desde={100} hasta={124} t0={T_CIENTO} t1={T_CIENTO + 0.8} y={430} prefijo="$" color={ROJO} />}
      {s >= T_MIL4 && s < T_DOSC && <Contador desde={1000} hasta={804} t0={T_OCHO} t1={T_OCHO + 0.9} y={430} prefijo="$" color={ORO} />}
      {s >= T_DOSC && s < T_DEJA && <Contador desde={0} hasta={196} t0={T_DOSC} t1={T_DOSC + 0.8} y={430} prefijo="-$" color={ROJO} />}
      <Destello t0={T_OCHO + 0.6} fuerza={0.3} />
      <Destello t0={T_RESTO} fuerza={0.25} />
      <AbsoluteFill style={{pointerEvents: 'none', background: `radial-gradient(circle at 50% 60%, rgba(255,200,61,${0.07 * lin(T_ASEG, T_ASEG + 0.5, 0, 1)}), transparent 60%)`}} />
    </AbsoluteFill>
  );
};
